        UBaseType_t ux_Saved_అంతరాయం_స్థితి;

        configASSERT( x_Task_గమ్యం_Notify );
        configASSERT( ux_సూచీ_గమ్యం_Notify < configTASK_NOTIFICATION_ARRAY_ENTRIES );

